test_that("ParametricSurvivalAnalysis (analysis 1) results match", {

  # Load from JASP example file
  jaspFile <- testthat::test_path("jaspfiles", "other", "flexsurv-lung.jasp")
  opts <- jaspTools::analysisOptions(jaspFile)[[1]]
  dataset <- jaspTools::extractDatasetFromJASPFile(jaspFile)

  # Run analysis
  set.seed(1)
  results <- jaspTools::runAnalysis("ParametricSurvivalAnalysis", dataset, opts)

  table <- results[["results"]][["coefficientsTable"]][["data"]]
  jaspTools::expect_equal_tables(table,
    list("shape", 1.36050776434482, 1.20536020716401, "", 0.0840472841601082, 1.53562509019403, "",
         "scale", 771.572846755434, 323.893561814016, "", 341.709179341196, 1838.02559864443, "", "age",
         -0.00756119587284572, -0.0210331600403129, 0.271315595485767, 0.00687357740944852,
         0.00591076829462149, -1.10003793111459, "sex (2)", 0.399487493409137, 0.154860784842978,
         0.00137085645053114, 0.12481183863364, 0.644114201975295, 3.20071795898908, "ph.ecog (1)",
         -0.296395572789955, -0.583130198717774, 0.042764678958556, 0.14629586471463,
         -0.00966094686213481, -2.02600103132179, "ph.ecog (2)", -0.662140921031336, -0.991806468233036,
         8.26327420856648e-05, 0.168199798466737, -0.332475373829636, -3.9366332603679, "ph.ecog (3)",
         -1.34846275788118, -2.81396577178145, 0.071320030828621, 0.747719358855554, 0.117040256019087,
         -1.80343432587477))

  table <- results[["results"]][["summaryTable"]][["data"]]
  jaspTools::expect_equal_tables(table,
    list(2275.53765358663, 2299.35639525974, 7L, -1130.76882679331))

})

